"""Write .env.example (local) and .env.docker.example (docker compose) from app/core/config.py.

    python scripts/generate_env_example.py
    cp .env.example .env                 # local run
    cp .env.docker.example .env.docker   # docker compose
"""

import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from app.core.config import Settings  # noqa: E402

HEADER = """# ============================================================================================
# {title}
# Generated by scripts/generate_env_example.py from app/core/config.py. Copy to {target} and edit
# values there; never commit real secrets. Staging/production refuse to start with development values.
# ============================================================================================
"""

LOCAL_OVERRIDES = {
    "ENVIRONMENT": "local",
    "LOG_JSON": "false",
    "CORS_ORIGINS": '["http://localhost:3000"]',
}
DOCKER_OVERRIDES = {
    **LOCAL_OVERRIDES,
    "LOG_JSON": "true",
    "REDIS_URL": "redis://redis:6379/0",
    "USER_MANAGEMENT_JWKS_URL": "http://user-management:8000/.well-known/jwks.json",
    # Every service is reached by its compose service name on the shared network, not localhost.
    "UPSTREAM_URLS": json.dumps({name: f"http://{name}:8000" for name in [
        "user-management", "catalog-service", "media-service", "subscription-service", "learning-service", "code-execution-service", "assessment-service", "proctoring-service",
        "certificate-service", "ai-gateway", "ai-tutor-service", "support-service", "career-service", "job-portal-service", "ai-interview-service", "notification-service",
        "analytics-service", "billing-service",
    ]}),
}


def _format(value: object) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return str(value).lower()
    if isinstance(value, list | dict):
        return json.dumps(value, separators=(",", ":"))
    return str(value)


def render(overrides: dict[str, str], title: str, target: str) -> str:
    source = (ROOT / "app/core/config.py").read_text(encoding="utf-8").splitlines()
    fields = Settings.model_fields
    lines = [HEADER.format(title=title, target=target)]
    comments: list[str] = []
    for raw in source:
        line = raw.strip()
        section = re.match(r"^# --- (.+?) ---$", line)
        if section:
            lines.append(f"\n# --- {section.group(1)} ---")
            comments = []
            continue
        if line.startswith("#"):
            comments.append(line)
            continue
        field = re.match(r"^([A-Z][A-Z0-9_]+)\s*:", line)
        if field and field.group(1) in fields:
            name = field.group(1)
            info = fields[name]
            lines.extend(comments)
            if info.description:
                lines.append(f"# {info.description}")
            default = info.get_default(call_default_factory=True)
            value = overrides.get(name, _format(default))
            prefix = "# " if default is None and name not in overrides else ""
            lines.append(f"{prefix}{name}={value}")
        comments = []
    return "\n".join(lines).rstrip() + "\n"


def main() -> None:
    (ROOT / ".env.example").write_text(render(LOCAL_OVERRIDES, "api-gateway: local settings", ".env"), encoding="utf-8")
    (ROOT / ".env.docker.example").write_text(
        render(DOCKER_OVERRIDES, "api-gateway: docker compose settings", ".env.docker"), encoding="utf-8"
    )
    print("Wrote .env.example and .env.docker.example")


if __name__ == "__main__":
    main()
